<?php
require_once __DIR__ . '/../config/database.php'; require_login(); $db=(new Database())->getConnection(); $uid=$_SESSION['user_id']; $success=''; $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();
$date=$_POST['trade_date']??date('Y-m-d');$asset=trim($_POST['asset']??'');$tf=trim($_POST['timeframe']??'');$setup=trim($_POST['setup']??'');$condition=trim($_POST['market_condition']??'');$entry=$_POST['entry_price']!==''?$_POST['entry_price']:null;$sl=$_POST['stop_loss']!==''?$_POST['stop_loss']:null;$tp=$_POST['take_profit']!==''?$_POST['take_profit']:null;$result=$_POST['result']??'';$rr=$_POST['risk_reward']!==''?$_POST['risk_reward']:0;$reason=trim($_POST['reason']??'');$lesson=trim($_POST['lesson_learned']??'');
if($asset && in_array($result,['Win','Loss','Break Even'],true)){ $q=$db->prepare("INSERT INTO trading_journal(user_id,trade_date,asset,timeframe,setup,market_condition,entry_price,stop_loss,take_profit,result,risk_reward,reason,lesson_learned) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)");$q->execute([$uid,$date,$asset,$tf,$setup,$condition,$entry,$sl,$tp,$result,$rr,$reason,$lesson]);$success="Jurnal berhasil disimpan."; } else $error="Asset dan hasil trade wajib diisi.";}
$q=$db->prepare("SELECT * FROM trading_journal WHERE user_id=? ORDER BY trade_date DESC,id DESC");$q->execute([$uid]);$journals=$q->fetchAll();
?>
