<form method="post" class="bg-white border rounded-3xl p-6 grid md:grid-cols-3 gap-4"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>">
<?php $fields=[['trade_date','Tanggal','date'],['asset','Asset / Pair','text'],['timeframe','Timeframe','text'],['setup','Setup','text'],['market_condition','Market Condition','text'],['entry_price','Entry','number'],['stop_loss','Stop Loss','number'],['take_profit','Take Profit','number'],['risk_reward','R:R','number']];foreach($fields as $f):?><div><label class="text-sm font-medium"><?=$f[1]?></label><input name="<?=$f[0]?>" type="<?=$f[2]?>" step="any" value="<?=e($f[0]==='trade_date'?date('Y-m-d'):'')?>" class="mt-1 w-full p-3 rounded-xl border"></div><?php endforeach;?>
<div><label class="text-sm font-medium">Result</label><select name="result" class="mt-1 w-full p-3 rounded-xl border"><option>Win</option><option>Loss</option><option>Break Even</option></select></div>
<div class="md:col-span-3"><label class="text-sm font-medium">Alasan / Thesis</label><textarea name="reason" rows="2" class="mt-1 w-full p-3 rounded-xl border"></textarea></div><div class="md:col-span-3"><label class="text-sm font-medium">Lesson Learned</label><textarea name="lesson_learned" rows="2" class="mt-1 w-full p-3 rounded-xl border"></textarea></div>
<button class="md:col-span-3 p-3 bg-blue-600 text-white rounded-xl font-bold">Simpan Jurnal</button></form>
<div class="mt-8 bg-white border rounded-3xl overflow-x-auto"><table class="w-full text-sm"><thead class="bg-slate-100"><tr><th class="p-4 text-left">Tanggal</th><th class="p-4 text-left">Asset</th><th class="p-4">TF</th><th class="p-4">Result</th><th class="p-4">R:R</th><th class="p-4 text-left">Setup</th></tr></thead><tbody><?php foreach($journals as $j):?><tr class="border-t"><td class="p-4"><?=e($j['trade_date'])?></td><td class="p-4 font-semibold"><?=e($j['asset'])?></td><td class="p-4 text-center"><?=e($j['timeframe'])?></td><td class="p-4 text-center"><?=e($j['result'])?></td><td class="p-4 text-center">1:<?=e($j['risk_reward'])?></td><td class="p-4"><?=e($j['setup'])?></td></tr><?php endforeach;if(!$journals):?><tr><td colspan="6" class="p-6 text-center text-slate-400">Belum ada jurnal.</td></tr><?php endif;?></tbody></table></div>
